'use strict';
let pendingAuthAction=null;
const day=86400000;
function signedIn(){return accountId!=='guest';}
function accountPlan(){if(accountId==='guest')return{kind:'guest'};const plan=accountPlans[accountId]||{kind:'free'};return plan.until&&plan.until<=Date.now()?{...plan,kind:'free'}:plan;}
function hasFullAccess(){return ['plus','trial'].includes(accountPlan().kind);}
function canSeeJob(job){return hasFullAccess()||job.firstObserved<=Date.now()-2*day;}
function accountIdentity(){return profileStore[accountId]?.identity||demoAccounts[accountId]||{name:'Member',email:''};}
function shortDate(value){return new Date(value).toLocaleDateString(I18n.locale,{day:'numeric',month:'long',year:'numeric'});}
function planLabel(){const plan=accountPlan();return plan.kind==='guest'?'Signed out':plan.kind==='plus'?'Justup Plus':plan.kind==='trial'?(plan.legacy?'Welcome month':'Free week'):'Free period ended';}
function renderAccountControl(){const identity=accountIdentity(),plan=accountPlan();$('#header-sign-in').hidden=signedIn();$('#account-initials').textContent=signedIn()?({plus:'VK',trial:'MY',free:'AX',legacy:'SM'}[accountId]||identity.name.slice(0,2).toUpperCase()):'Settings';$('#account-initials').classList.toggle('guest-label',!signedIn());const badge=$('.account-plan');badge.hidden=!signedIn();badge.textContent=plan.kind==='plus'?'PLUS':plan.kind==='trial'?'TRIAL':'FREE';$('#account-open').setAttribute('aria-label','Settings');}
function hiddenMatchCount(){return current().query?jobs.filter(job=>searchMatches(job)&&!canSeeJob(job)).length:0;}
function openSettings(){renderSettings();if(!$('#settings-dialog').open)$('#settings-dialog').showModal();}
function renderAccessNotice(){const el=$('#access-notice');el.hidden=!current().query||accountPlan().kind==='plus';if(el.hidden){el.innerHTML='';return;}const plan=accountPlan();if(plan.kind==='trial'){el.className='access-notice trial-notice';el.innerHTML=`<span class="eyebrow">${plan.legacy?'YOUR WELCOME MONTH':'YOUR FREE WEEK'}</span><p>Full access until <span>${shortDate(plan.until)}</span>.</p><a class="text-link" href="#membership">Explore Plus ↗</a>`;return;}
const hidden=hiddenMatchCount();el.className='access-notice';el.innerHTML=`<div class="access-copy"><span class="eyebrow">LATEST MATCHES</span><h2>${hidden?`${hidden.toLocaleString(I18n.locale)} recent ${hidden===1?'match hidden':'matches hidden'}`:(signedIn()?'Keep your search fresh.':'See what just came in.')}</h2><p>${signedIn()?'Your free period has ended. Subscribe to see the latest matches. Your searches and followed companies stay saved.':'Sign in for a free week of full access. Older matches are available in the preview below.'}</p></div><div class="access-actions">${signedIn()?'<a class="button dark" href="#membership">See Plus plans ↗</a>':'<button class="button dark" data-sign-in>Start your free week ↗</button><span class="small-print">No card required.</span>'}</div>`;}
function updateEditionDate(){$('#edition-date').textContent=new Date().toLocaleDateString(I18n.locale,{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toLocaleUpperCase(I18n.locale);}
function openSignIn(reason,action=null){pendingAuthAction=action;$('#sign-in-reason').textContent=reason||'Sign in for your first free week, saved searches and followed companies.';$('#sign-in-email').value='';$('#sign-in-dialog').showModal();$('#sign-in-email').focus();}
function restoreProfile(id){accountId=id;saved=profileStore[id]||{};postingLanguages=new Set(saved.postingLanguages||[]);requests=(saved.requests||[]).filter(r=>companyFor(r.company));viewed=new Set(saved.viewed||[]);followedCompanies.clear();for(const id of saved.followedCompanies||[])if(companyFor(id))followedCompanies.add(id);searches=Array.isArray(saved.searches)?saved.searches:[];starterSearch={...blankSearch(),...(saved.starterSearch||{})};activeSearch=searches.some(s=>s.id===saved.activeSearch)?saved.activeSearch:searches[0]?.id??null;premium=accountPlan().kind==='plus';previousAccessKind=accountPlan().kind;}
function switchAccount(id,carryGuest=false){if(!demoAccounts[id]&&!profileStore[id])return;const guestData=accountId==='guest'&&carryGuest?captureProfile():null;persist();if(guestData){const target=profileStore[id]||{};const combined=[...(target.searches||[])];for(const search of guestData.searches)if(!combined.some(existing=>existing.query===search.query))combined.push({...search});const guestActive=guestData.searches.find(s=>s.id===guestData.activeSearch);profileStore[id]={...target,postingLanguages:target.postingLanguages??guestData.postingLanguages,searches:combined,activeSearch:guestActive?combined.find(s=>s.query===guestActive.query)?.id:target.activeSearch,starterSearch:guestData.starterSearch,viewed:[...new Set([...(target.viewed||[]),...guestData.viewed])]};}
queryTimer++;requestGeneration++;feed.generation++;companyFeed.generation++;companyFeed.key=null;disposeCompanyGlobe?.();disposeCompanyGlobe=null;restoreProfile(id);$('#toast').hidden=true;$('#announcer').textContent='';loadSearch();route();if($('#settings-dialog').open)renderSettings();persist();}
function renderSettings(){const identity=accountIdentity(),plan=accountPlan();const allIds=[...new Set([...Object.keys(demoAccounts),...Object.keys(profileStore)])];$('#settings-content').innerHTML=`<div class="section-heading"><h1 id="settings-title">Settings.</h1></div><p class="page-intro">Make this edition yours.</p><div class="settings-grid"><div><section class="settings-section"><span class="eyebrow">ACCOUNT</span><h2>${signedIn()?escapeHTML(identity.name):'Your edition starts here.'}</h2>${signedIn()?`<p class="account-email" data-no-translate>${escapeHTML(identity.email)}</p><button class="button outline" data-logout>Log out ↗</button>`:'<p>Keep your searches, follow companies and see the latest matches.</p><button class="button dark" data-sign-in>Sign in ↗</button>'}</section><section class="settings-section"><span class="eyebrow">YOUR ACCESS</span><h2>${planLabel()}</h2><p>${plan.kind==='guest'?'Your first week of full access is free. No card required.':plan.kind==='trial'?`Full access until <span>${shortDate(plan.until)}</span>.`:plan.kind==='plus'?`${plan.renews?'Renews on':'Access continues until'} <span>${shortDate(plan.until)}</span>.`:'Your searches and followed companies stay saved. Subscribe to see the latest matches.'}</p><a class="button dark" href="#membership">${plan.kind==='plus'?'Manage plan':'Explore Plus'} ↗</a></section></div><div><section class="settings-section"><span class="eyebrow">LANGUAGE & DISPLAY</span><label class="settings-label" for="language-choice">Interface language</label><select id="language-choice"><option value="auto">Browser preference</option><option value="en" data-no-translate>English</option><option value="de" data-no-translate>Deutsch</option><option value="fr" data-no-translate>Français</option><option value="es" data-no-translate>Español</option></select><p class="settings-hint">Browser preference: <span data-no-translate>${I18n.names[I18n.browserLanguage()]}</span></p><p class="settings-hint">Job titles and company descriptions stay in their original language.</p><div class="posting-language-setting"><span class="settings-label">Posting languages</span><button type="button" class="posting-language-setting-button" data-posting-languages aria-haspopup="dialog"><span data-posting-language-summary data-no-translate></span><span aria-hidden="true">↗</span></button><p class="settings-hint">Matches any selected language. Applies to all your searches.</p></div><label class="check-label settings-motion"><input id="settings-reduced" type="checkbox" ${forcedReduced?'checked':''}> Reduce motion</label><p class="settings-hint">Your system motion preference is also respected.</p></section><section class="settings-section preview-accounts"><span class="eyebrow">PROTOTYPE CONTROLS</span><label class="settings-label" for="preview-account">Preview accounts</label><select id="preview-account">${allIds.map(id=>{const identity=profileStore[id]?.identity||demoAccounts[id]||{name:'Member'};const plan=accountPlans[id];const state=id==='guest'?'Signed out':plan?.kind==='plus'?'Plus':plan?.kind==='trial'?(plan.legacy?'Welcome month':'Free week'):'Free period ended';return `<option value="${escapeHTML(id)}" ${id===accountId?'selected':''}>${id==='guest'?'Signed out':escapeHTML(identity.name)+' · '+state}</option>`;}).join('')}</select><p class="settings-hint">Temporary accounts for trying every access state. Each account keeps its own searches and follows.</p><p class="settings-hint">Sign-in and payments are simulated in this prototype.</p></section></div></div>`;$('#language-choice').value=I18n.choice;renderPostingLanguageControls();}
function renderMembership(){const plan=accountPlan();$('#membership-page').innerHTML=`<a class="back" href="#settings">← Settings</a><div class="section-heading"><h1>${plan.kind==='plus'?'Your Plus edition.':'Keep your edition coming.'}</h1><span class="eyebrow">JUSTUP PLUS</span></div><div class="membership-layout"><div class="membership-pitch"><h2>Full access.<br>Clear sources.</h2><p>See the newest matches from company career pages, always in recency order.</p><ul><li>Every eligible match from the last 14 days</li><li>Live updates as matching jobs arrive</li><li>Saved searches and followed companies</li><li>Priority for your company requests</li></ul><p class="small-print">Employers can’t buy a place in your results.</p></div><div class="membership-choice">${plan.kind==='guest'?'<div class="membership-trial"><span class="eyebrow">YOUR FIRST WEEK</span><h2>Start with full access.</h2><p>Try your edition free for a week. No card required.</p><button class="button dark" data-sign-in>Start your free week ↗</button></div>':plan.kind==='trial'?`<div class="membership-status"><span class="eyebrow">${plan.legacy?'WELCOME MONTH':'FREE WEEK ACTIVE'}</span><p>Full access until <span>${shortDate(plan.until)}</span>.</p></div>`:plan.kind==='plus'?`<div class="membership-status"><span class="eyebrow">PLUS ACTIVE</span><p>${plan.renews?'Renews on':'Access continues until'} <span>${shortDate(plan.until)}</span>.</p></div>`:''}<fieldset class="plan-options"><legend>Choose your rhythm</legend><label class="plan-option"><input type="radio" name="billing-period" value="weekly" ${plan.interval==='weekly'?'checked':''}><span><b>Weekly</b><small>Cancel renewal at any time</small></span><strong>$3<span>/week</span></strong></label><label class="plan-option"><input type="radio" name="billing-period" value="monthly" ${plan.interval!=='weekly'?'checked':''}><span><b>Monthly</b><small>Cancel renewal at any time</small></span><strong>$10<span>/month</span></strong></label></fieldset><button class="button dark membership-submit" ${signedIn()?'data-activate-plan':'data-sign-in'}>${plan.kind==='plus'?'Update plan':'Continue with Plus'} ↗</button>${plan.kind==='plus'?`<button class="text-link cancel-renewal" ${plan.renews?'data-cancel-plan':'data-resume-plan'}>${plan.renews?'Cancel renewal':'Resume renewal'}</button>`:''}<p class="small-print">Illustrative prices. This prototype does not collect payments.</p><p class="settings-hint">${plan.kind==='plus'?'Cancelling renewal keeps access open through your paid period.':'No automatic charge at the end of your free period.'}</p></div></div>`;}
function activatePlan(){if(!signedIn()){openSignIn();return;}const interval=$('input[name="billing-period"]:checked')?.value||'monthly';const currentPlan=accountPlan();accountPlans[accountId]={kind:'plus',interval,renews:true,until:currentPlan.kind==='plus'?currentPlan.until:Date.now()+(interval==='weekly'?7:30)*day};premium=true;previousAccessKind='plus';persist();resetFeed();updateBadges();renderMembership();toast(currentPlan.kind==='plus'?'Plan updated.':'Your Plus preview is active.');}
function completeSignIn(email){const normalized=email.trim().toLowerCase();const match=Object.entries(demoAccounts).find(([id,identity])=>id!=='guest'&&identity.email===normalized);const id=match?.[0]||'member:'+normalized;if(!profileStore[id])profileStore[id]={identity:match?undefined:{name:normalized.split('@')[0].replace(/[._-]+/g,' '),email:normalized}};if(!accountPlans[id])accountPlans[id]={kind:'trial',until:Date.now()+7*day};const action=pendingAuthAction;$('#sign-in-dialog').close();pendingAuthAction=null;switchAccount(id,true);if(action?.kind==='follow')toggleFollow(action.id);else if(action?.kind==='priority')prioritize(action.id);else if(action?.kind==='request'){if(location.hash!=='#request'){location.hash='request';requestForm();}acceptCompany(action.company);}toast('You’re signed in. Your edition is ready.');}
function refreshLanguage(){renderPostingLanguageControls();const focused=document.activeElement?.id;updateEditionDate();renderAccessNotice();if($('#settings-dialog').open){renderSettings();if(focused)document.getElementById(focused)?.focus({preventScroll:true});}for(const row of $$('#feed [data-job]')){const job=jobs.find(job=>job.id===row.dataset.job);if(job){const time=$('time',row);time.title=fullTime(job);time.setAttribute('aria-label',fullTime(job));}}if(pageName==='membership')renderMembership();companyFeed.key=null;if(pageName==='companies')renderCompanies();if(pageName==='company')renderCompany(location.hash.split('/')[1]);I18n.refresh();}
function initSurfaces(){$('#account-open').addEventListener('click',openSettings);document.addEventListener('click',event=>{if(event.target.closest('#settings-dialog a[href]'))$('#settings-dialog').close();if(event.target.closest('[data-sign-in]')){openSignIn();return;}if(event.target.closest('[data-logout]')){switchAccount('guest');toast('You’re signed out.');return;}if(event.target.closest('[data-activate-plan]')){activatePlan();return;}if(event.target.closest('[data-cancel-plan]')){$('#cancel-plan-dialog').showModal();return;}if(event.target.closest('[data-resume-plan]')){accountPlans[accountId].renews=true;persist();renderMembership();toast('Renewal resumed.');}});document.addEventListener('change',event=>{if(event.target.id==='preview-account'){switchAccount(event.target.value);$('#preview-account')?.focus({preventScroll:true});announce('Preview account changed.');}if(event.target.id==='language-choice'){I18n.set(event.target.value);refreshLanguage();}if(event.target.id==='settings-reduced'){forcedReduced=event.target.checked;$('#reduced-motion').checked=forcedReduced;document.body.classList.toggle('reduce-motion',reduced());persist();}});$('#sign-in-form').addEventListener('submit',event=>{event.preventDefault();completeSignIn($('#sign-in-email').value);});$('#sign-in-dialog').addEventListener('close',()=>pendingAuthAction=null);$('#confirm-cancel-plan').addEventListener('click',()=>{if(accountPlan().kind!=='plus')return;accountPlans[accountId].renews=false;$('#cancel-plan-dialog').close();persist();renderMembership();toast('Renewal cancelled. Your current access stays open.');});window.addEventListener('languagechange',()=>{if(I18n.choice==='auto'){I18n.set('auto');refreshLanguage();}});}

let previousAccessKind=null;
function syncAccess(){const kind=accountPlan().kind;if(previousAccessKind!==null&&previousAccessKind!==kind){premium=kind==='plus';resetFeed();updateBadges();if($('#settings-dialog').open)renderSettings();if(pageName==='membership')renderMembership();}previousAccessKind=kind;}
setInterval(syncAccess,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncAccess();});
